import pytest

from minimum_spanning_tree import minimum_spanning_tree


def _is_connected(edges, nodes):
    """辅助函数：判断给定边集合是否连通所有节点。"""
    if not nodes:
        return True
    adjacency = {n: set() for n in nodes}
    for u, v in edges:
        adjacency[u].add(v)
        adjacency[v].add(u)
    start = next(iter(nodes))
    visited = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        stack.extend(adjacency[node] - visited)
    return visited == set(nodes)


def test_minimum_spanning_tree_docstring_example():
    """docstring 示例：四节点图，期望值来自 docstring。"""
    weight_by_edge = {
        (1, 2): 10,
        (2, 3): 15,
        (3, 4): 10,
        (1, 4): 10,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2), (3, 4), (1, 4)}


def test_minimum_spanning_tree_single_edge():
    """单边图：最小规模连通图，MST 即该边。"""
    weight_by_edge = {(1, 2): 5}
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2)}


def test_minimum_spanning_tree_triangle_equal_weights():
    """三角形等权图：多个合法 MST，仅验证大小与连通性。

    期望值来源不明（取决于排序稳定性），需人工确认。
    """
    weight_by_edge = {
        (1, 2): 1,
        (2, 3): 1,
        (1, 3): 1,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert isinstance(result, set)
    assert len(result) == 2
